export function cleanNick(value){if(typeof value!=='string')throw Error('Придумай ник');const nick=value.normalize('NFKC').trim();if(nick.length<2||nick.length>20||! /^[\p{L}\p{N}_ -]+$/u.test(nick))throw Error('Ник: 2–20 букв, цифр, пробелов, дефисов или _');const norm=nick.toLowerCase().replace(/[\s_-]/g,'').replace(/0/g,'o').replace(/3/g,'з').replace(/6/g,'б').replace(/4/g,'ч');if(/(хуй|хуя|хуе|хуё|пизд|бляд|блят|ебать|ебал|ебан|ёбан|заеб|сук[аи]|сука|мудак|гандон|fuck|shit|bitch|cunt|pizd|blyad|suka|huy|khuy)/i.test(norm))throw Error('Этот ник не подходит. Придумай другой, без мата.');return nick;}
export const RANKS=[...['Бронза','Силвер','Голд'].flatMap(n=>['I','II','III','IV'].map(s=>n+' '+s)),'Феникс','Чемпион','Элита','Легенда','Ты класс','Сокол','Мега крутой'];
export function calculateRank(results,previous=null){if(results.length!==5)throw Error('Нужно завершить 5 партий');const wins=results.filter(r=>r.won).length,damage=results.reduce((s,r)=>s+r.damage,0);let index=wins===5&&damage===0?15:Math.min(14,Math.floor(wins*2.5+Math.max(0,1-damage/500)*2));const timed=results.every(r=>Number.isFinite(r.elapsedMs)&&r.elapsedMs<30000&&r.elapsedMs>=0);if(previous?.index>=15&&wins===5&&damage===0&&timed)index=Math.min(18,previous.index+1);return {index,name:RANKS[index],wins,damage};}
export function rankMark(rank){return RANKS[rank?.index]||'Без звания';}
